<template><AppShell :title="pageTitle"><template #default="{ can, setError }"><v-btn v-if="can('sales.manage')" block class="mb-3" prepend-icon="mdi-plus" @click="dialog=true">매출 등록</v-btn><v-card variant="outlined" class="mb-3"><v-card-text><div class="text-caption">조회 매출 합계</div><div class="text-h5 font-weight-bold">{{ total.toLocaleString() }}원</div></v-card-text></v-card><v-list lines="three"><v-list-item v-for="s in sales" :key="s.id" :title="`${s.sales_date} · ${s.store?.name}`" :subtitle="`${s.items?.length??0}개 품목 · ${saleTotal(s).toLocaleString()}원 · ${s.status}`"/></v-list><v-empty-state v-if="!sales.length" title="매출 기록이 없습니다."/><v-dialog v-model="dialog" max-width="400"><v-card title="간편 매출 등록"><v-card-text><v-alert type="info" variant="tonal" density="compact" class="mb-3">데모에서는 한 번에 한 제품을 빠르게 등록할 수 있습니다.</v-alert><v-select v-model="form.store_id" :items="stores" item-title="name" item-value="id" label="점포" variant="outlined"/><v-text-field v-model="form.sales_date" type="date" label="매출일" variant="outlined"/><v-text-field v-model="item.product_id" type="number" label="제품 ID" variant="outlined"/><v-number-input v-model="item.quantity" label="수량" :min="1" variant="outlined"/><v-number-input v-model="item.actual_unit_price" label="판매 단가" :min="0" variant="outlined"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="dialog=false">취소</v-btn><v-btn @click="save(setError)">저장</v-btn></v-card-actions></v-card></v-dialog></template></AppShell></template>
<script setup>
import{computed,onMounted,ref}from'vue';import AppShell from'../../components/layout/AppShell.vue';const pageTitle='매출 관리';const sales=ref([]),dialog=ref(false);const form=ref({store_id:null,sales_date:new Date().toISOString().slice(0,10),note:''});const item=ref({product_id:null,quantity:1,actual_unit_price:0});const stores=computed(()=>[...new Map(sales.value.filter(s=>s.store).map(s=>[s.store.id,s.store])).values()]);const saleTotal=s=>s.items?.reduce((a,i)=>a+i.net_amount,0)??0;const total=computed(()=>sales.value.reduce((a,s)=>a+saleTotal(s),0));async function load(){sales.value=(await window.axios.get('/tillwhite/api/sales')).data.sales;}async function save(err){try{await window.axios.post('/tillwhite/api/sales',{...form.value,items:[item.value]});dialog.value=false;await load();}catch(e){err(e.response?.data?.message??'매출 저장 실패');}}onMounted(load);
</script>
